module tb_TopModule;
    logic       clk;
    logic       resetn;
    logic [2:0] r;
    logic [2:0] g;

    TopModule uut (
        .clk(clk),
        .resetn(resetn),
        .r(r),
        .g(g)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        resetn = 0;
        r = 3'b000;
        @(posedge clk);
        #1;
        if (g !== 3'b000) begin
            $display("SELFTEST FAIL: Reset state failed (g=%b)", g);
            $finish;
        end

        resetn = 1;
        @(posedge clk);
        #1;

        // Test A -> B (r[0]=1)
        r = 3'b001;
        @(posedge clk);
        #1;
        if (g !== 3'b001) begin
            $display("SELFTEST FAIL: Failed to grant device 0 when r[0]=1 (g=%b)", g);
            $finish;
        end

        // Keep r[0]=1, should stay in B
        r = 3'b111; // r[1] and r[2] also high, but already granted B, should hold B
        @(posedge clk);
        #1;
        if (g !== 3'b001) begin
            $display("SELFTEST FAIL: Failed to hold grant B when r[0]=1 (g=%b)", g);
            $finish;
        end

        // Drop r[0]=0, should return to A
        r = 3'b110; // r[2]=1, r[1]=1
        @(posedge clk);
        #1;
        if (g !== 3'b000) begin
            $display("SELFTEST FAIL: Failed to return to A when r[0]=0 (g=%b)", g);
            $finish;
        end

        // Now in A with r[2:1]=11, priority should pick device 1 (C)
        @(posedge clk);
        #1;
        if (g !== 3'b010) begin
            $display("SELFTEST FAIL: Priority test failed, expected device 1 grant (g=%b)", g);
            $finish;
        end

        // Drop r[1], should return to A
        r = 3'b100; // only r[2]
        @(posedge clk);
        #1;
        if (g !== 3'b000) begin
            $display("SELFTEST FAIL: Failed to return to A from C (g=%b)", g);
            $finish;
        end

        // Now in A with r[2]=1, should go to D
        @(posedge clk);
        #1;
        if (g !== 3'b100) begin
            $display("SELFTEST FAIL: Failed to grant device 2 when r[2]=1 (g=%b)", g);
            $finish;
        end

        // Drop r[2], return to A
        r = 3'b000;
        @(posedge clk);
        #1;
        if (g !== 3'b000) begin
            $display("SELFTEST FAIL: Failed to return to A from D (g=%b)", g);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

